export interface BrandAuthAafConfig {
    defaultRole: string;
    attributesField: string;
    usernameField: string;
    postLoginRedir: string;
    opts: Record<string, unknown>;
    templatePath: string;
}

export interface BrandAuthOidcConfig {
    debugMode: boolean;
    discoverAttemptsMax: number;
    discoverFailureSleep: number;
    defaultRole: string;
    postLoginRedir: string;
    claimMappings: Record<string, string>;
    opts: {
        issuer: string;
        client: {
            client_id: string;
            client_secret: string;
            redirect_uris: string[];
            post_logout_redirect_uris: string[];
        };
        params: {
            scope: string;
        };
    };
    templatePath: string;
}

export interface SolrPreIndexConfig {
    move?: SolrPreIndexMoveConfig[];
    copy?: SolrPreIndexCopyConfig[];
    flatten?: SolrPreIndexFlattenConfig;
}

export interface I18nNextInitConfig {
    supportedLngs: string[];
    preload: string[];
    debug: boolean;
    fallbackLng: string | string[];
    lowerCaseLng: boolean;
    initImmediate: boolean;
    load?: 'all' | 'currentOnly' | 'languageOnly';
    skipOnVariables: boolean;
    returnEmptyString: boolean;
    ns: string[];
    detection: I18nDetectionConfig;
}
